 const auto baseline=raster.stats();const auto resources=renderer.stats();scene.updatePose({{},1,.01,{},{}});scene.uploadAnimations(renderer);composition.setEntries(renderer,scene.entries());composition.present(renderer);allocations=0;countAllocations=true;try{for(unsigned n=0;n<100;++n){const double t=.02+n*.001;scene.updatePose({core::Matrix4::rotation(0,.0001*n,0),1,t,{},{}});scene.uploadAnimations(renderer);composition.setEntries(renderer,scene.entries());composition.present(renderer);}}catch(...){countAllocations=false;throw;}countAllocations=false;check(allocations==0,"Warm Settings tilt and feedback allocate no heap");check(raster.stats().rasterizations==baseline.rasterizations&&renderer.stats().textureUploads==resources.textureUploads,"Numeric Settings frames retain all pixels");
