 state.escape(1);publish(1);publish(1.3);state.perform("appIcon",1.4);publish(1.4);publish(1.7);check(state.view().page==modules::SettingsPage::icons,"Original icon page uses explicit prepared source pictures");const auto beforeBurst=raster.stats().rasterizations;for(unsigned n=0;n<32;++n)state.scroll({200,100},7,1.8);check(raster.stats().rasterizations==beforeBurst,"Burst input only changes portable page before one frame");publish(1.8);scene.setFeedback("appIcon:rhineLab",true,1.9);publish(1.97);check(scene.stats().retiredParts==0&&raster.stats().entries<LayerRasterizer::maximumEntries,"Recycled page and icon controls stay bounded");
